<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Database\Eloquent\Model;use Illuminate\Http\Request;use Illuminate\Support\Str;
abstract class CrudController extends Controller { protected string $model; protected array $rules=[]; protected array $defaults=[]; public function index(Request $r){$m=$this->model;return response()->json($m::query()->latest()->paginate(100));} public function show(int $id){$m=$this->model;return response()->json(['data'=>$m::findOrFail($id)]);} public function store(Request $r){$m=$this->model;$d=$r->validate($this->rules);$d=array_merge($this->defaults,$d);if(array_key_exists('slug',(new $m)->getFillable())&&empty($d['slug']))$d['slug']=Str::slug($d['name']??$d['title']??Str::random(8));return response()->json(['data'=>$m::create($d)],201);} public function update(Request $r,int $id){$m=$this->model;/** @var Model $row */$row=$m::findOrFail($id);$rules=[];foreach($this->rules as $k=>$v)$rules[$k]=str_replace('required','sometimes',$v);$d=$r->validate($rules);$row->update($d);return response()->json(['data'=>$row->fresh()]);} public function destroy(int $id){$m=$this->model;$m::findOrFail($id)->delete();return response()->json(['message'=>'Deleted.']);} }
